/* Stardew Valley set additions — cards appended after stardew-valley.js.
   (stardew-valley.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'stardew-valley.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('stardew-valley');
  if (!S) return;
  var extra = [{"name":"Ginger Island","rarity":"legendary","id":"ginger-island","subtitle":"Locations","details":"Tropical island reached by Willy's repaired boat, home to a volcano, walnut hunting, Leo, island farming, and a beach resort.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e4/Ginger_Island.png"},{"name":"Skull Cavern","rarity":"legendary","id":"skull-cavern","subtitle":"Locations","details":"Bottomless desert cavern of iridium, treasure rooms, serpents, and prismatic shards, where staircases replace any safe depth.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2c/Skullkeyentrance.jpg"},{"name":"Volcano Dungeon","rarity":"legendary","id":"volcano-dungeon","subtitle":"Locations","details":"Ten-floor island dungeon of lava, cinder shards, dwarvish sentries, and a summit forge for enchanting and combining rings.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d3/VolcanoDungeon_Entryway.png"},{"name":"Calico Desert","rarity":"epic","id":"calico-desert","subtitle":"Locations","details":"Sun-baked region reached by bus, holding the Oasis, Skull Cavern, the casino's secret door, and Starfruit's favourite soil.","image":"https://stardewvalleywiki.com/mediawiki/images/7/71/DesertPondSouth.png"},{"name":"Secret Woods","rarity":"epic","id":"secret-woods","subtitle":"Locations","details":"Cindersap clearing west of the farm where hardwood stumps regrow, fireflies gather, and Old Master Cannoli waits for sweetness.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9c/SecretWoods.png"},{"name":"Witch's Swamp","rarity":"epic","id":"witchs-swamp","subtitle":"Locations","details":"Murky path beyond the railroad where a witch's hut, dark shrines, and a goblin with a taste for void mayonnaise await.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9f/Witch%27s_Swamp.png"},{"name":"The Sewers","rarity":"epic","id":"the-sewers","subtitle":"Locations","details":"Underground home of Krobus and the dwarf-adjacent shadows, reached with the rusty key and holding mutant carp in green water.","image":"https://stardewvalleywiki.com/mediawiki/images/1/11/KrobusInSewer.png"},{"name":"The Summit","rarity":"epic","id":"the-summit","subtitle":"Locations","details":"Quiet peak beyond the railroad reached after true completion, where the valley spreads below and a perfect farm is honoured.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d7/The_Summit.png"},{"name":"Pelican Town","rarity":"rare","id":"pelican-town","subtitle":"Locations","details":"Heart of the valley with Pierre's shop, the clinic, the saloon, and the town square where festivals fill the streets all year.","image":"https://stardewvalleywiki.com/mediawiki/images/2/25/Pelican_Town.png"},{"name":"The Mines","rarity":"rare","id":"the-mines","subtitle":"Locations","details":"One-hundred-twenty floors of stone, ice, and lava beneath the mountain, holding gems, monsters, and a Stardrop chest at the bottom.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cb/MinesEntrance.png"},{"name":"Community Center","rarity":"rare","id":"community-center","subtitle":"Locations","details":"Town hall restored bundle by bundle with the Junimos' help, or lost to a Joja warehouse if the membership route is chosen.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a8/Community_Center.png"},{"name":"Stardrop Saloon","rarity":"rare","id":"stardrop-saloon","subtitle":"Locations","details":"Gus's evening hub on the town square, serving pizza and beer beside arcade cabinets, a jukebox, and Shane's corner stool.","image":"https://stardewvalleywiki.com/mediawiki/images/6/69/Saloon.png"},{"name":"Museum","rarity":"rare","id":"museum","subtitle":"Locations","details":"Gunther's collection hall east of town, displaying every donated artifact and mineral and rewarding a complete collection.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ae/Museum.png"},{"name":"Movie Theatre","rarity":"rare","id":"movie-theatre","subtitle":"Locations","details":"Cinema built from the old Joja warehouse or an abandoned site, screening films, hosting the crane game, and serving snacks.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bb/Movie_Theater.png"},{"name":"Pirate Cove","rarity":"rare","id":"pirate-cove","subtitle":"Locations","details":"Ginger Island cove opened on certain rainy evenings, where pirate games reward lucky farmers and stingrays swim in secret.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a0/Pirate_Cove.png"},{"name":"The Farm","rarity":"rare","id":"the-farm","subtitle":"Locations","details":"The farmer's own land west of town, in many layouts from riverland to wilderness, where every season's work begins at dawn.","image":"https://stardewvalleywiki.com/mediawiki/images/d/de/Standard_Farm.png"},{"name":"Cindersap Forest","rarity":"uncommon","id":"cindersap-forest","subtitle":"Locations","details":"Western woods of hardwood, ponds, and seasonal forage, home to Leah's cottage, Marnie's ranch, the lake, and spring onions.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0c/CindersapForest.png"},{"name":"The Beach","rarity":"uncommon","id":"the-beach","subtitle":"Locations","details":"Sandy shore south of town with Willy's shop, Elliott's cabin, tide pools, the resort dock, and festivals on the sand.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e4/Beach_Overview.jpg"},{"name":"The Mountains","rarity":"uncommon","id":"the-mountains","subtitle":"Locations","details":"Northern region of the lake, Robin's shop, the Mines, and the Adventurer's Guild, where quarry stone and hot springs meet.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b5/The_Mountain.png"},{"name":"Quarry","rarity":"uncommon","id":"quarry","subtitle":"Locations","details":"Rocky dig site east of the mountains unlocked by bridge repair, respawning stone, geodes, and gems beside its haunted mine.","image":"https://stardewvalleywiki.com/mediawiki/images/2/28/Quarry.png"},{"name":"Railroad","rarity":"uncommon","id":"railroad","subtitle":"Locations","details":"Northern stop where trains rumble past, a spa steams, and witches, goblins, and summit paths share the shadow of the cliffs.","image":"https://stardewvalleywiki.com/mediawiki/images/b/ba/Railroad.png"},{"name":"Spa","rarity":"uncommon","id":"spa","subtitle":"Locations","details":"Mountain bathhouse where still water restores energy and health for free, split into pools beside the railroad tracks.","image":"https://stardewvalleywiki.com/mediawiki/images/e/eb/Spa.png"},{"name":"Greenhouse","rarity":"uncommon","id":"greenhouse","subtitle":"Locations","details":"Glass building where crops grow in any season once repaired, holding fruit trees, kegs, and the farm's most reliable harvests.","image":"https://stardewvalleywiki.com/mediawiki/images/9/93/Greenhouse.png"},{"name":"Farm Cave","rarity":"uncommon","id":"farm-cave","subtitle":"Locations","details":"Choice of mushroom or fruit bat cave offered by Demetrius, quietly producing cave goods while the farmer is elsewhere.","image":"https://stardewvalleywiki.com/mediawiki/images/e/eb/Cave_Entrance.png"},{"name":"Adventurer's Guild","rarity":"uncommon","id":"adventurers-guild","subtitle":"Locations","details":"Guild hall east of the Mines where Marlon and Gil tally monster goals, sell gear, and recover items lost in the deep.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8c/Adventurer%27s_Guild.gif"},{"name":"Wizard's Tower","rarity":"uncommon","id":"wizards-tower","subtitle":"Locations","details":"Cindersap tower of M. Rasmodius, filled with arcane circles, shrines, and the gateway to magical farm buildings.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6f/Wizzard_tower.gif"},{"name":"Mutant Bug Lair","rarity":"uncommon","id":"mutant-bug-lair","subtitle":"Locations","details":"Sewer-side lair of mutant grubs and flies, home to the slimejack and a chest reached only by fighting through the swarm.","image":"https://stardewvalleywiki.com/mediawiki/images/4/47/Mutant_Bug_Lair.png"},{"name":"Pierre's General Store","rarity":"common","id":"pierres-general-store","subtitle":"Locations","details":"Town shop run by Pierre and his family, selling seasonal seeds, backpacks, bouquets, and wallpaper six days a week.","image":"https://stardewvalleywiki.com/mediawiki/images/4/4a/Pierres_shop.png"},{"name":"JojaMart","rarity":"common","id":"jojamart","subtitle":"Locations","details":"Corporate superstore east of town selling cheaper seeds and memberships, open long hours, and employing Sam and Shane.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f9/Jojamart.png"},{"name":"Carpenter's Shop","rarity":"common","id":"carpenters-shop","subtitle":"Locations","details":"Robin's mountain shop for farm buildings, upgrades, furniture, and wood and stone, closed when she dances at aerobics.","image":"https://stardewvalleywiki.com/mediawiki/images/c/ca/Carpenter%27s_Shop.png"},{"name":"Marnie's Ranch","rarity":"common","id":"marnies-ranch","subtitle":"Locations","details":"Marnie's southern ranch selling coop and barn animals, hay, heaters, and the auto-grabber, when she is actually at the counter.","image":"https://stardewvalleywiki.com/mediawiki/images/8/87/Ranch.png"},{"name":"Fish Shop","rarity":"common","id":"fish-shop","subtitle":"Locations","details":"Willy's beach shack selling rods, bait, tackle, and crab pots, and buying every fish the valley's waters give up.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2b/Fish_Shop.png"},{"name":"Blacksmith","rarity":"common","id":"blacksmith","subtitle":"Locations","details":"Clint's shop east of town for tool upgrades, geodes cracked open, and coal and bars for the forge-minded farmer.","image":"https://stardewvalleywiki.com/mediawiki/images/b/be/Blacksmith.png"},{"name":"Leah's Cottage","rarity":"common","id":"leahs-cottage","subtitle":"Locations","details":"Artist's home in Cindersap Forest, filled with sculptures and paintings, opening to friends and smelling of wood and rain.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f8/Leah%27s_Cottage.png"},{"name":"Elliott's Cabin","rarity":"common","id":"elliotts-cabin","subtitle":"Locations","details":"Writer's cabin on the beach, draft pages and lobster dinners inside, with a locked door that friendship and stories open.","image":"https://stardewvalleywiki.com/mediawiki/images/4/40/Elliott%27s_Cabin.png"},{"name":"The Oasis","rarity":"common","id":"the-oasis","subtitle":"Locations","details":"Sandy's desert shop in the Oasis, selling deluxe speed-gro, cactus and rhubarb seed, and welcoming every bus passenger warmly.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7d/Oasis.png"},{"name":"Prismatic Shard","rarity":"chase","id":"prismatic-shard","subtitle":"Artifacts, Minerals & Gems","details":"Rainbow mineral of unknown origin, loved by almost everyone, used for the Galaxy Sword, enchanting tools, and priceless trades.","image":"https://stardewvalleywiki.com/mediawiki/images/5/56/Prismatic_Shard.png"},{"name":"Ancient Seed","rarity":"legendary","id":"ancient-seed","subtitle":"Artifacts, Minerals & Gems","details":"Dry museum seed crafted into plantable ancient seeds after donation, unlocking a crop older than the valley itself.","image":"https://stardewvalleywiki.com/mediawiki/images/a/af/Ancient_Seed.png"},{"name":"Dinosaur Egg","rarity":"legendary","id":"dinosaur-egg","subtitle":"Artifacts, Minerals & Gems","details":"Museum egg best hatched before it is donated, incubating into a coop dinosaur that lays more eggs for mayonnaise and display.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a1/Dinosaur_Egg.png"},{"name":"Golden Mask","rarity":"epic","id":"golden-mask","subtitle":"Artifacts, Minerals & Gems","details":"Ornate museum mask of gold, dug from desert and bone-rich places, gleaming with a civilisation the valley forgot.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7e/Golden_Mask.png"},{"name":"Golden Relic","rarity":"epic","id":"golden-relic","subtitle":"Artifacts, Minerals & Gems","details":"Golden museum relic dug from sandy and ancient places, a heavy remnant prized by Gunther's desert-minded collection.","image":"https://stardewvalleywiki.com/mediawiki/images/3/37/Golden_Relic.png"},{"name":"Dwarvish Helm","rarity":"epic","id":"dwarvish-helm","subtitle":"Artifacts, Minerals & Gems","details":"Dwarvish museum helm of iron and gold, dug from deep places, proof of the craftsmanship of the people under the mountain.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8b/Dwarvish_Helm.png"},{"name":"Dwarf Gadget","rarity":"epic","id":"dwarf-gadget","subtitle":"Artifacts, Minerals & Gems","details":"Dwarvish museum machine required, with other donations, for a farm computer and counted among the valley's strangest finds.","image":"https://stardewvalleywiki.com/mediawiki/images/5/58/Dwarf_Gadget.png"},{"name":"Diamond","rarity":"epic","id":"diamond","subtitle":"Artifacts, Minerals & Gems","details":"Brilliant gem cut from geodes and deep stone, loved by Marnie, Maru, and Penny and used in rings, machines, and gifts.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ea/Diamond.png"},{"name":"Emerald","rarity":"rare","id":"emerald","subtitle":"Artifacts, Minerals & Gems","details":"Green gem of the Mines and geodes, loved by Clint, Emily, and Penny and set into spinners, rings, and crystalariums.","image":"https://stardewvalleywiki.com/mediawiki/images/6/6a/Emerald.png"},{"name":"Ruby","rarity":"rare","id":"ruby","subtitle":"Artifacts, Minerals & Gems","details":"Red gem of deep stone and geodes, loved by Clint and Emily, glowing warm in crystalariums and artisan jewellery alike.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a9/Ruby.png"},{"name":"Aquamarine","rarity":"rare","id":"aquamarine","subtitle":"Artifacts, Minerals & Gems","details":"Blue-green gem of frosty depths, loved by Clint and the Dwarf, used in sprinklers, rings, and fishing tackle alike.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a2/Aquamarine.png"},{"name":"Jade","rarity":"rare","id":"jade","subtitle":"Artifacts, Minerals & Gems","details":"Green gem loved by Clint and Emily, duplicated happily in crystalariums and carved into jade rings and staircases in trade.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7e/Jade.png"},{"name":"Elvish Jewelry","rarity":"rare","id":"elvish-jewelry","subtitle":"Artifacts, Minerals & Gems","details":"Fine old jewellery for the museum, dug from fishing chests and rich soil, too elegant for any living valley wardrobe.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9d/Elvish_Jewelry.png"},{"name":"Ornamental Fan","rarity":"rare","id":"ornamental-fan","subtitle":"Artifacts, Minerals & Gems","details":"Decorative museum fan fished and dug from coastal places, painted for a hand that stopped waving it long ago.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ab/Ornamental_Fan.png"},{"name":"Star Shards","rarity":"rare","id":"star-shards","subtitle":"Artifacts, Minerals & Gems","details":"Cluster of tiny star-like crystals for the museum, dug from stony places and shining like a captured constellation.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3f/Star_Shards.png"},{"name":"Amethyst","rarity":"uncommon","id":"amethyst","subtitle":"Artifacts, Minerals & Gems","details":"Purple gem loved most famously by Abigail, who accepts it with suspiciously hungry delight, and by Clint and Emily too.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2e/Amethyst.png"},{"name":"Topaz","rarity":"uncommon","id":"topaz","subtitle":"Artifacts, Minerals & Gems","details":"Warm yellow gem of shallow stone and geodes, loved by Clint and Emily and used in sprinklers and golden cooking alike.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a5/Topaz.png"},{"name":"Iridium Ore","rarity":"uncommon","id":"iridium-ore","subtitle":"Artifacts, Minerals & Gems","details":"Dark ore smelted into the valley's finest bars, mined deep in Skull Cavern and the volcano and used in almost everything.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e9/Iridium_Ore.png"},{"name":"Fire Quartz","rarity":"uncommon","id":"fire-quartz","subtitle":"Artifacts, Minerals & Gems","details":"Hot crystal found in lava-level geodes and stone, warm to the touch and used in bombs, sprinklers, and spicy cooking.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5b/Fire_Quartz.png"},{"name":"Frozen Tear","rarity":"uncommon","id":"frozen-tear","subtitle":"Artifacts, Minerals & Gems","details":"Pale crystal wept by the frozen deep, loved by Sebastian, and used in sprinklers, rings, and winter crafting recipes.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ec/Frozen_Tear.png"},{"name":"Earth Crystal","rarity":"uncommon","id":"earth-crystal","subtitle":"Artifacts, Minerals & Gems","details":"Round crystal humming with static from stony earth, used in lightning rods, sprinklers, and earthy rings and recipes.","image":"https://stardewvalleywiki.com/mediawiki/images/7/74/Earth_Crystal.png"},{"name":"Quartz","rarity":"uncommon","id":"quartz","subtitle":"Artifacts, Minerals & Gems","details":"Clear crystal duplicated endlessly in crystalariums, loved by villagers as a gift and used in sprinklers and refinement.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cf/Quartz.png"},{"name":"Ancient Doll","rarity":"uncommon","id":"ancient-doll","subtitle":"Artifacts, Minerals & Gems","details":"Worn museum doll with an unsettling stare, dug from farms, forests, and mountains and wanted for a children's bundle.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c0/Ancient_Doll.png"},{"name":"Strange Doll","rarity":"uncommon","id":"strange-doll","subtitle":"Artifacts, Minerals & Gems","details":"Green or yellow museum doll dug from valley soil, stranger than its cousin and best donated quickly to Gunther's case.","image":"https://stardewvalleywiki.com/mediawiki/images/3/39/Strange_Doll_%28green%29.png"},{"name":"Anchor","rarity":"uncommon","id":"anchor","subtitle":"Artifacts, Minerals & Gems","details":"Heavy museum anchor fished from coastal water, rusted proof that bigger boats once worked the valley's quiet shore.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c0/Anchor.png"},{"name":"Bone Flute","rarity":"uncommon","id":"bone-flute","subtitle":"Artifacts, Minerals & Gems","details":"Museum flute carved from bone, donated toward a flute block reward and sounding a note older than Pelican Town.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fc/Bone_Flute.png"},{"name":"Chipped Amphora","rarity":"uncommon","id":"chipped-amphora","subtitle":"Artifacts, Minerals & Gems","details":"Cracked museum vessel dug from mountain and forest soil, its painted pattern broken long before the farmer's spade.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9e/Chipped_Amphora.png"},{"name":"Dwarf Scroll I","rarity":"common","id":"dwarf-scroll-i","subtitle":"Artifacts, Minerals & Gems","details":"Red-bowed scroll that begins the Dwarvish set, found by tilling and fighting in the Mines and Skull Cavern's soil.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b9/Dwarf_Scroll_I.png"},{"name":"Dwarf Scroll II","rarity":"common","id":"dwarf-scroll-ii","subtitle":"Artifacts, Minerals & Gems","details":"Green-ribboned scroll of the Dwarvish set, found on the frost floors where frozen jellies and bats guard the deep.","image":"https://stardewvalleywiki.com/mediawiki/images/c/ca/Dwarf_Scroll_II.png"},{"name":"Dwarf Scroll III","rarity":"common","id":"dwarf-scroll-iii","subtitle":"Artifacts, Minerals & Gems","details":"Blue-ribboned scroll of the Dwarvish set, dropped and dug in the deeper Mines where slimes and shadows gather.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ec/Dwarf_Scroll_III.png"},{"name":"Dwarf Scroll IV","rarity":"common","id":"dwarf-scroll-iv","subtitle":"Artifacts, Minerals & Gems","details":"Yellow-ribboned scroll completing the Dwarvish set, found from monsters almost anywhere and unlocking the translation guide.","image":"https://stardewvalleywiki.com/mediawiki/images/8/85/Dwarf_Scroll_IV.png"},{"name":"Arrowhead","rarity":"common","id":"arrowhead","subtitle":"Artifacts, Minerals & Gems","details":"Museum point dug from mountain and lake soil, sharp after all these years and made for a bowstring long rotted away.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d1/Arrowhead.png"},{"name":"Chewing Stick","rarity":"common","id":"chewing-stick","subtitle":"Artifacts, Minerals & Gems","details":"Gnawed museum stick dug from forest, mountain, and lake soil, carrying tooth marks from an owner best left unknown.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d2/Chewing_Stick.png"},{"name":"Glass Shards","rarity":"common","id":"glass-shards","subtitle":"Artifacts, Minerals & Gems","details":"Coloured museum fragments fished and dug from the beach, beautiful enough to display and sharp enough to respect.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b9/Glass_Shards.png"},{"name":"Prehistoric Handaxe","rarity":"common","id":"prehistoric-handaxe","subtitle":"Artifacts, Minerals & Gems","details":"Stone museum axe dug from forest, mountain, and beach soil, heavy in the hand and older than any farm tool.","image":"https://stardewvalleywiki.com/mediawiki/images/0/07/Prehistoric_Handaxe.png"},{"name":"Skeletal Tail","rarity":"common","id":"skeletal-tail","subtitle":"Artifacts, Minerals & Gems","details":"Curved museum bone dug from desert sands and bone nodes, the tail of something the valley no longer hosts.","image":"https://stardewvalleywiki.com/mediawiki/images/2/29/Skeletal_Tail.png"},{"name":"Nautilus Fossil","rarity":"common","id":"nautilus-fossil","subtitle":"Artifacts, Minerals & Gems","details":"Fossil shell for the museum, fished and dug from the beach, carrying a spiral older than the ocean that left it.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3b/Nautilus_Fossil.png"},{"name":"Amphibian Fossil","rarity":"common","id":"amphibian-fossil","subtitle":"Artifacts, Minerals & Gems","details":"Fossil frog for the museum, fished and dug from forest and mountain water, leaping no more but perfectly preserved.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cf/Amphibian_Fossil.png"},{"name":"Palm Fossil","rarity":"common","id":"palm-fossil","subtitle":"Artifacts, Minerals & Gems","details":"Fossil frond for the museum, dug from desert and beach soil, from a jungle that stood where sand now drifts.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e1/Palm_Fossil.png"},{"name":"Trilobite","rarity":"common","id":"trilobite","subtitle":"Artifacts, Minerals & Gems","details":"Fossil arthropod for the museum, dug from the beach soil, armoured in segments from a sea older than the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/2/2b/Trilobite.png"},{"name":"Chicken Statue","rarity":"common","id":"chicken-statue","subtitle":"Artifacts, Minerals & Gems","details":"Odd little farming statue dug from the farm itself, later earning a furniture twin among Gunther's donation rewards.","image":"https://stardewvalleywiki.com/mediawiki/images/a/af/Chicken_Statue.png"},{"name":"Rusty Cog","rarity":"common","id":"rusty-cog","subtitle":"Artifacts, Minerals & Gems","details":"Rusted museum cog dug and fished from farm and mountain soil, from a machine no living villager remembers building.","image":"https://stardewvalleywiki.com/mediawiki/images/7/74/Rusty_Cog.png"},{"name":"Galaxy Sword","rarity":"chase","id":"galaxy-sword","subtitle":"Items, Tools & Artisan Goods","details":"Blade claimed by holding a prismatic shard between the desert's three pillars, the first and finest of the galaxy weapons.","image":"https://stardewvalleywiki.com/mediawiki/images/4/44/Galaxy_Sword.png"},{"name":"Stardrop","rarity":"chase","id":"stardrop","subtitle":"Items, Tools & Artisan Goods","details":"Mysterious fruit eaten the moment it is found, permanently raising maximum energy and tasting exactly like a favourite thing.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a5/Stardrop.png"},{"name":"Gold Clock","rarity":"legendary","id":"gold-clock","subtitle":"Items, Tools & Artisan Goods","details":"Wizard-built farm clock costing a fortune in gold, stopping fence decay and keeping debris from ever spoiling the farm.","image":"https://stardewvalleywiki.com/mediawiki/images/b/b5/Gold_Clock.png"},{"name":"Return Scepter","rarity":"legendary","id":"return-scepter","subtitle":"Items, Tools & Artisan Goods","details":"Krobus's costly sceptre, held aloft to warp instantly home to the farmhouse door from anywhere in the valley and beyond.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f3/Return_Scepter.png"},{"name":"Golden Scythe","rarity":"legendary","id":"golden-scythe","subtitle":"Items, Tools & Artisan Goods","details":"Wider, hay-rich scythe taken from a grim statue at the end of the Quarry Mine, swinging farther than any ordinary blade.","image":"https://stardewvalleywiki.com/mediawiki/images/3/33/Golden_Scythe.png"},{"name":"Iridium Sprinkler","rarity":"epic","id":"iridium-sprinkler","subtitle":"Items, Tools & Artisan Goods","details":"Sprinkler watering the twenty-four tiles around it each morning, built from iridium and the backbone of a hands-free farm.","image":"https://stardewvalleywiki.com/mediawiki/images/9/90/Iridium_Sprinkler.png"},{"name":"Crystalarium","rarity":"epic","id":"crystalarium","subtitle":"Items, Tools & Artisan Goods","details":"Gem machine that copies whatever mineral is placed inside, endlessly replicating diamonds and gems, but never a prismatic shard.","image":"https://stardewvalleywiki.com/mediawiki/images/6/63/Crystalarium.png"},{"name":"Junimo Hut","rarity":"epic","id":"junimo-hut","subtitle":"Items, Tools & Artisan Goods","details":"Wizard-built hut whose Junimo residents harvest ripe crops around it, carry them inside, and ask only for shelter in return.","image":"https://stardewvalleywiki.com/mediawiki/images/7/73/Junimo_Hut.png"},{"name":"Earth Obelisk","rarity":"epic","id":"earth-obelisk","subtitle":"Items, Tools & Artisan Goods","details":"Wizard-built obelisk that warps the farmer to the mountains in a blink, one of four great towers for crossing the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3c/Earth_Obelisk.png"},{"name":"Iridium Band","rarity":"epic","id":"iridium-band","subtitle":"Items, Tools & Artisan Goods","details":"Crafted band glowing with light, pulling in nearby items and strengthening attacks, the ring a delver never wants to lose.","image":"https://stardewvalleywiki.com/mediawiki/images/7/77/Iridium_Band.png"},{"name":"Caviar","rarity":"epic","id":"caviar","subtitle":"Items, Tools & Artisan Goods","details":"Sturgeon roe aged in a preserves jar into the valley's fanciest artisan good, served tiny and priced accordingly.","image":"https://stardewvalleywiki.com/mediawiki/images/8/89/Caviar.png"},{"name":"Auto-Grabber","rarity":"rare","id":"auto-grabber","subtitle":"Items, Tools & Artisan Goods","details":"Marnie's machine that gathers eggs, milk, wool, and truffles from a building each morning so the farmer never has to.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0a/Auto-Grabber.png"},{"name":"Slime Charmer Ring","rarity":"rare","id":"slime-charmer-ring","subtitle":"Items, Tools & Artisan Goods","details":"Guild reward ring earned by slaying a thousand slimes, making every slime's touch harmless from the day it is won.","image":"https://stardewvalleywiki.com/mediawiki/images/5/51/Slime_Charmer_Ring.png"},{"name":"Warp Totem: Farm","rarity":"rare","id":"warp-totem-farm","subtitle":"Items, Tools & Artisan Goods","details":"Carved totem consumed in a flash of light to warp home to the farm, crafted, found, and treasured by stranded delvers.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e4/Warp_Totem_Farm.png"},{"name":"Rain Totem","rarity":"rare","id":"rain-totem","subtitle":"Items, Tools & Artisan Goods","details":"Carved totem that calls rain for tomorrow, barring festivals and winter, for farmers who plan their watering by magic.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f7/Rain_Totem.png"},{"name":"Keg","rarity":"rare","id":"keg","subtitle":"Items, Tools & Artisan Goods","details":"Oak and iron machine that turns fruit into wine, vegetables into juice, hops into pale ale, and honey into mead.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7c/Keg.png"},{"name":"Preserves Jar","rarity":"uncommon","id":"preserves-jar","subtitle":"Items, Tools & Artisan Goods","details":"Jar that turns fruit into jelly, vegetables into pickles, and roe into aged roe or caviar with nothing but time.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1e/Preserves_Jar.png"},{"name":"Cheese Press","rarity":"uncommon","id":"cheese-press","subtitle":"Items, Tools & Artisan Goods","details":"Press that turns milk into cheese and large milk into gold-star cheese, ready for cakes, poppers, and pizza alike.","image":"https://stardewvalleywiki.com/mediawiki/images/7/79/Cheese_Press.png"},{"name":"Loom","rarity":"uncommon","id":"loom","subtitle":"Items, Tools & Artisan Goods","details":"Frame that weaves wool into cloth, turning a sheep's fleece or a rabbit's wool into tailoring's most useful fabric.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3b/Loom.png"},{"name":"Oil Maker","rarity":"uncommon","id":"oil-maker","subtitle":"Items, Tools & Artisan Goods","details":"Maker that presses truffles into prized oil and corn or sunflower seeds into cooking oil for the farmhouse kitchen.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c5/Oil_Maker.png"},{"name":"Cask","rarity":"uncommon","id":"cask","subtitle":"Items, Tools & Artisan Goods","details":"Cellar barrel that ages wine, cheese, beer, and juice up to iridium quality while the seasons turn quietly above.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7c/Cask.png"},{"name":"Bee House","rarity":"uncommon","id":"bee-house","subtitle":"Items, Tools & Artisan Goods","details":"Box where bees make honey from nearby flowers, the blossom deciding whether the jar sells plain or like a bouquet.","image":"https://stardewvalleywiki.com/mediawiki/images/c/ce/Bee_House.png"},{"name":"Tapper","rarity":"uncommon","id":"tapper","subtitle":"Items, Tools & Artisan Goods","details":"Brass tap driven into maple, oak, and pine trees, gathering syrup, resin, and tar while the farmer does other work.","image":"https://stardewvalleywiki.com/mediawiki/images/d/da/Tapper.png"},{"name":"Lightning Rod","rarity":"uncommon","id":"lightning-rod","subtitle":"Items, Tools & Artisan Goods","details":"Rod that catches lightning during storms, shielding farm buildings and leaving a battery pack humming at its base.","image":"https://stardewvalleywiki.com/mediawiki/images/6/62/Lightning_Rod.png"},{"name":"Wine","rarity":"uncommon","id":"wine","subtitle":"Items, Tools & Artisan Goods","details":"Fruit aged in a keg until it becomes the drink of celebrations, loved by Harvey and Leah and better with every season.","image":"https://stardewvalleywiki.com/mediawiki/images/6/69/Wine.png"},{"name":"Cheese","rarity":"uncommon","id":"cheese","subtitle":"Items, Tools & Artisan Goods","details":"Milk pressed into a golden wheel, eaten, gifted, and melted into half the valley's favourite cooked dishes.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a5/Cheese.png"},{"name":"Truffle Oil","rarity":"uncommon","id":"truffle-oil","subtitle":"Items, Tools & Artisan Goods","details":"Pig-found truffles pressed into fragrant oil, loved by Harvey, used in rain totems, and sold for serious gold.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3d/Truffle_Oil.png"},{"name":"Honey","rarity":"uncommon","id":"honey","subtitle":"Items, Tools & Artisan Goods","details":"Bees' work in a jar, plain or flower-flavoured, eaten for energy, brewed into mead, and gifted across the valley.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c6/Honey.png"},{"name":"Aged Roe","rarity":"uncommon","id":"aged-roe","subtitle":"Items, Tools & Artisan Goods","details":"Fish roe aged in a preserves jar until it deepens in flavour, with sturgeon roe alone graduating to caviar.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0e/Aged_Roe.png"},{"name":"Mayonnaise","rarity":"common","id":"mayonnaise","subtitle":"Items, Tools & Artisan Goods","details":"Eggs beaten into jars by machine, spread on almost everything, and loved or hated by villagers with strong opinions.","image":"https://stardewvalleywiki.com/mediawiki/images/4/4e/Mayonnaise.png"},{"name":"Cloth","rarity":"common","id":"cloth","subtitle":"Items, Tools & Artisan Goods","details":"Wool woven on a loom into soft fabric for shirts, millinery, and Emily's most loved gifts from a thoughtful farmer.","image":"https://stardewvalleywiki.com/mediawiki/images/5/51/Cloth.png"},{"name":"Jelly","rarity":"common","id":"jelly","subtitle":"Items, Tools & Artisan Goods","details":"Fruit sealed in a preserves jar until it sets sweet and bright, keeping summer on the pantry shelf all winter.","image":"https://stardewvalleywiki.com/mediawiki/images/0/05/Jelly.png"},{"name":"Pickles","rarity":"common","id":"pickles","subtitle":"Items, Tools & Artisan Goods","details":"Vegetables sealed in a preserves jar until they pickle sharp and savoury, boosting Harvey's day and many a lunch.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c7/Pickles.png"},{"name":"Juice","rarity":"common","id":"juice","subtitle":"Items, Tools & Artisan Goods","details":"Vegetables pressed through a keg into fresh juice, a quick, green way to drink a garden that grew too much.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f1/Juice.png"},{"name":"Pale Ale","rarity":"common","id":"pale-ale","subtitle":"Items, Tools & Artisan Goods","details":"Hops steeped in a keg into a frothy ale, loved by Pam and Gus and poured nightly at the Stardrop Saloon.","image":"https://stardewvalleywiki.com/mediawiki/images/7/78/Pale_Ale.png"},{"name":"Mead","rarity":"common","id":"mead","subtitle":"Items, Tools & Artisan Goods","details":"Honey fermented in a keg into golden mead, loved by Willy and Pam and warmer than any winter evening deserves.","image":"https://stardewvalleywiki.com/mediawiki/images/8/84/Mead.png"},{"name":"Coffee","rarity":"common","id":"coffee","subtitle":"Items, Tools & Artisan Goods","details":"Beans brewed in a keg into a speed-giving cup, loved by Harvey and carried at a jog through every busy morning.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e9/Coffee.png"},{"name":"Green Tea","rarity":"common","id":"green-tea","subtitle":"Items, Tools & Artisan Goods","details":"Tea leaves steeped in a keg into a calming drink loved by Caroline, granting a brief store of extra energy.","image":"https://stardewvalleywiki.com/mediawiki/images/8/8f/Green_Tea.png"},{"name":"Smoked Fish","rarity":"common","id":"smoked-fish","subtitle":"Items, Tools & Artisan Goods","details":"Fish cured in a smoker until rich and firm, doubling its worth and keeping the catch's quality through the smoke.","image":"https://stardewvalleywiki.com/mediawiki/images/4/4c/Smoked_Fish.png"},{"name":"Dried Fruit","rarity":"common","id":"dried-fruit","subtitle":"Items, Tools & Artisan Goods","details":"Fruit dried in a dehydrator into chewy keepsakes for trails and gifts, with grapes alone becoming raisins instead.","image":"https://stardewvalleywiki.com/mediawiki/images/6/66/Dried_Fruit.png"},{"name":"Perfection","rarity":"chase","id":"perfection","subtitle":"Festivals, Events & Quests","details":"Reaching one hundred percent of everything the valley asks — crops, catches, cooking, friendship, and walnuts — tracked in Qi's room.","image":"https://stardewvalleywiki.com/mediawiki/images/d/db/Statue_Of_True_Perfection.png"},{"name":"Grandpa's Evaluation","rarity":"legendary","id":"grandpas-evaluation","subtitle":"Festivals, Events & Quests","details":"Candle-lit judgement at Grandpa's shrine at the start of year three, scoring the farm and rewarding success with a statue.","image":"https://stardewvalleywiki.com/mediawiki/images/5/51/Grandpa_Speaking.png"},{"name":"Night Market","rarity":"epic","id":"night-market","subtitle":"Festivals, Events & Quests","details":"Three winter nights on the beach with merchants, a submarine, a mermaid show, and goods that appear nowhere else all year.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/NightMarket.jpg"},{"name":"Spirit's Eve","rarity":"epic","id":"spirits-eve","subtitle":"Festivals, Events & Quests","details":"Spooky fall festival with a haunted maze, a golden pumpkin prize, and the whole town in costume under a dark sky.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a9/Spirits_Eve.png"},{"name":"Stardew Valley Fair","rarity":"rare","id":"stardew-valley-fair","subtitle":"Festivals, Events & Quests","details":"Fall fair on the town square with games, tokens, a grange contest, and a Stardrop waiting at the star token shop.","image":"https://stardewvalleywiki.com/mediawiki/images/4/45/StardewValleyFair.png"},{"name":"Community Center Completion","rarity":"rare","id":"community-center-completion","subtitle":"Festivals, Events & Quests","details":"Ceremony celebrating the Junimos' restored hall, with Pierre's shop finally open daily and the town gathered in thanks.","image":"https://stardewvalleywiki.com/mediawiki/images/c/ce/CC_Complete.png"},{"name":"Golden Walnut","rarity":"rare","id":"golden-walnut","subtitle":"Festivals, Events & Quests","details":"Hard golden currency hidden all over Ginger Island, spent with the parrots on bridges, volcano shortcuts, and island wonders.","image":"https://stardewvalleywiki.com/mediawiki/images/5/54/Golden_Walnut.png"},{"name":"Egg Festival","rarity":"uncommon","id":"egg-festival","subtitle":"Festivals, Events & Quests","details":"Spring festival opening the year, with strawberries for sale, a feast on the square, and the great egg hunt at noon.","image":"https://stardewvalleywiki.com/mediawiki/images/2/20/Egg_Festival.png"},{"name":"Flower Dance","rarity":"uncommon","id":"flower-dance","subtitle":"Festivals, Events & Quests","details":"Spring meadow dance in Cindersap Forest, where a four-heart partner, matching outfits, and flower crowns mark the season.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ad/Flower_Festival.jpg"},{"name":"Luau","rarity":"uncommon","id":"luau","subtitle":"Festivals, Events & Quests","details":"Summer beach potluck where the whole town's ingredients meet in one soup pot under the Governor's careful spoon.","image":"https://stardewvalleywiki.com/mediawiki/images/a/af/Luau.png"},{"name":"Dance of the Moonlight Jellies","rarity":"uncommon","id":"dance-of-the-moonlight-jellies","subtitle":"Festivals, Events & Quests","details":"Summer night when glowing jellies drift past the beach dock, and the town watches in silence from Willy's pier.","image":"https://stardewvalleywiki.com/mediawiki/images/3/35/Dance_Of_The_Moonlight_Jellies.jpg"},{"name":"Festival of Ice","rarity":"uncommon","id":"festival-of-ice","subtitle":"Festivals, Events & Quests","details":"Winter festival on the frozen Cindersap lake, with ice fishing, snowmen, and villagers gathered on the shining ice.","image":"https://stardewvalleywiki.com/mediawiki/images/1/13/Festival_of_Ice.png"},{"name":"Feast of the Winter Star","rarity":"uncommon","id":"feast-of-the-winter-star","subtitle":"Festivals, Events & Quests","details":"Winter holiday of secret gift-giving in the town square, where a mystery friend, a feast, and Pierre's shop close the year.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ae/Feast_of_the_Winterstar.png"},{"name":"Desert Festival","rarity":"uncommon","id":"desert-festival","subtitle":"Festivals, Events & Quests","details":"Spring gathering in the Calico Desert with races, shops, free cactus fruit, and villagers in festival outfits for three days.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f3/Desert_Festival.png"},{"name":"Queen of Sauce","rarity":"uncommon","id":"queen-of-sauce","subtitle":"Festivals, Events & Quests","details":"Television cooking show airing Sundays and rerunning Wednesdays, teaching a new recipe to any farmer who remembers to watch.","image":"https://stardewvalleywiki.com/mediawiki/images/a/af/Queen_of_Sauce.png"},{"name":"Trout Derby","rarity":"common","id":"trout-derby","subtitle":"Festivals, Events & Quests","details":"Two summer days on the town river when rainbow trout wearing tags are worth prizes for the anglers who land them.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1d/Trout_Derby.png"},{"name":"SquidFest","rarity":"common","id":"squidfest","subtitle":"Festivals, Events & Quests","details":"Two winter nights on the ocean pier when catching enough squid earns tiers of nautical prizes in the cold and dark.","image":"https://stardewvalleywiki.com/mediawiki/images/3/31/SquidFest.png"},{"name":"Egg Hunt","rarity":"common","id":"egg-hunt","subtitle":"Festivals, Events & Quests","details":"Timed spring scramble through town and forest for hidden eggs, with a straw hat for the winner and strawberries after.","image":"https://stardewvalleywiki.com/mediawiki/images/7/76/EggHuntEggs.jpg"},{"name":"Grange Display","rarity":"common","id":"grange-display","subtitle":"Festivals, Events & Quests","details":"Nine-item fall display judged against Pierre's at the fair, where quality, variety, and price decide the star tokens.","image":"https://stardewvalleywiki.com/mediawiki/images/b/bc/GrangeDisplay123Points.png"},{"name":"Ice Fishing Contest","rarity":"common","id":"ice-fishing-contest","subtitle":"Festivals, Events & Quests","details":"Two-minute winter contest on the frozen lake, won by landing the most fish before the Festival of Ice calls time.","image":"https://stardewvalleywiki.com/mediawiki/images/1/13/Festival_of_Ice.png"},{"name":"Mermaid Show","rarity":"common","id":"mermaid-show","subtitle":"Festivals, Events & Quests","details":"Night Market boat show where a mermaid sings and a pattern of shells, tapped in order, yields a single shining pearl.","image":"https://stardewvalleywiki.com/mediawiki/images/6/66/Mermaid.png"},{"name":"Submarine Ride","rarity":"common","id":"submarine-ride","subtitle":"Festivals, Events & Quests","details":"Night Market dive to the ocean floor, fishing up midnight squid, spook fish, and blobfish from the submarine window.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/NightMarket.jpg"},{"name":"Junimo Kart","rarity":"common","id":"junimo-kart","subtitle":"Festivals, Events & Quests","details":"Arcade race in the saloon where a minecart, fruit, and impossible jumps separate casual players from true kart champions.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f3/Junimo_Kart.png"},{"name":"Journey of the Prairie King","rarity":"common","id":"journey-of-the-prairie-king","subtitle":"Festivals, Events & Quests","details":"Arcade quest in the saloon, blasting through prairie stages, spending coins on upgrades, and facing down a grim outlaw.","image":"https://stardewvalleywiki.com/mediawiki/images/1/18/JOPK_logo.png"},{"name":"Secret Notes","rarity":"common","id":"secret-notes","subtitle":"Festivals, Events & Quests","details":"Folded clues found across the valley after earning the magnifying glass, pointing to gifts, treasure, and villagers' secrets.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ec/Secret_Note.png"},{"name":"Journal Scraps","rarity":"common","id":"journal-scraps","subtitle":"Festivals, Events & Quests","details":"Torn island pages dug, fished, and fought for across Ginger Island, pointing to buried walnuts and island lore alike.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c4/Journal_Scrap.png"},{"name":"Monster Slayer Goals","rarity":"common","id":"monster-slayer-goals","subtitle":"Festivals, Events & Quests","details":"Guild board of monster tallies beside the Mines, traded in for rings, weapons, and boots as each quota falls.","image":"https://stardewvalleywiki.com/mediawiki/images/3/31/Adventurer%27s_Guild_Interior.png"},{"name":"Casino","rarity":"common","id":"casino","subtitle":"Festivals, Events & Quests","details":"Back-room den in the Oasis where Qi coins buy slots and blackjack, reached only after a chain of mysterious club errands.","image":"https://stardewvalleywiki.com/mediawiki/images/4/4f/Casino.png"},{"name":"Crane Game","rarity":"common","id":"crane-game","subtitle":"Festivals, Events & Quests","details":"Cinema claw machine stocked with seasonal prizes, posters, and plants, won by patience, positioning, and one steady drop.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3c/CraneGame.png"},{"name":"Luau Soup","rarity":"common","id":"luau-soup","subtitle":"Festivals, Events & Quests","details":"The Luau's communal pot itself, where one ingredient — superb, poor, or unspeakable — decides the Governor's whole verdict.","image":"https://stardewvalleywiki.com/mediawiki/images/a/af/Luau.png"},{"name":"Golden Chicken","rarity":"legendary","id":"golden-chicken","subtitle":"Animals","details":"Rare golden layer hatched from a golden egg after perfection's door opens, laying golden eggs for the luckiest coops.","image":"https://stardewvalleywiki.com/mediawiki/images/3/3c/Golden_Chicken.png"},{"name":"Blue Chicken","rarity":"epic","id":"blue-chicken","subtitle":"Animals","details":"Striking blue layer that can appear at Marnie's after Shane's friendship deepens, laying ordinary eggs in extraordinary plumage.","image":"https://stardewvalleywiki.com/mediawiki/images/6/61/Blue_Chicken.png"},{"name":"Dinosaur","rarity":"epic","id":"dinosaur","subtitle":"Animals","details":"Coop dinosaur hatched from a found dinosaur egg, laying fresh dinosaur eggs for mayonnaise, donations, and more dinosaurs.","image":"https://stardewvalleywiki.com/mediawiki/images/8/89/Dinosaur.png"},{"name":"Void Chicken","rarity":"rare","id":"void-chicken","subtitle":"Animals","details":"Black layer hatched from a void egg, laying void eggs for mayonnaise, strange buns, and Krobus's favourite breakfasts.","image":"https://stardewvalleywiki.com/mediawiki/images/6/67/Void_Chicken.png"},{"name":"Ostrich","rarity":"rare","id":"ostrich","subtitle":"Animals","details":"Long-necked barn layer from a Ginger Island egg, producing large ostrich eggs that hatch and sell in impressive dozens.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ad/Ostrich.png"},{"name":"Pig","rarity":"rare","id":"pig","subtitle":"Animals","details":"Adult barn animal that snuffles up truffles in the yard on fair days, never in winter, and pays for its keep manyfold.","image":"https://stardewvalleywiki.com/mediawiki/images/3/30/Pig.png"},{"name":"Rabbit","rarity":"rare","id":"rabbit","subtitle":"Animals","details":"Soft barn-coop layer giving wool without shears and, on lucky high-friendship days, a prized rabbit's foot for gifts.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fd/Rabbit.png"},{"name":"Cow","rarity":"uncommon","id":"cow","subtitle":"Animals","details":"Gentle barn animal milked daily once grown, giving milk and large milk for cheese, cakes, and a hundred recipes.","image":"https://stardewvalleywiki.com/mediawiki/images/3/36/White_Cow.png"},{"name":"Goat","rarity":"uncommon","id":"goat","subtitle":"Animals","details":"Barn animal milked every other day, giving goat milk for goat cheese loved by Leah and for cheeses of every quality.","image":"https://stardewvalleywiki.com/mediawiki/images/5/52/Goat.png"},{"name":"Sheep","rarity":"uncommon","id":"sheep","subtitle":"Animals","details":"Woolly barn animal sheared once grown, filling looms with wool for cloth and warming the barn through every winter.","image":"https://stardewvalleywiki.com/mediawiki/images/c/cc/Sheep.png"},{"name":"Duck","rarity":"uncommon","id":"duck","subtitle":"Animals","details":"Coop bird laying duck eggs and occasionally a feather, loved by Elliott and Leo and splashing happily in any pond.","image":"https://stardewvalleywiki.com/mediawiki/images/3/38/Duck.png"},{"name":"Chicken","rarity":"uncommon","id":"chicken","subtitle":"Animals","details":"Classic coop bird laying an egg every morning once grown, in white or brown, and starting almost every farm's animal story.","image":"https://stardewvalleywiki.com/mediawiki/images/2/22/White_Chicken.png"},{"name":"Horse","rarity":"uncommon","id":"horse","subtitle":"Animals","details":"Saddled companion from the stable who carries the farmer far faster than walking and always finds the way home overnight.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c3/Horse.png"},{"name":"Cat","rarity":"uncommon","id":"cat","subtitle":"Animals","details":"Farm pet adopted from Marnie, drinking from its bowl, following the farmer about, and quietly leaving gifts at full friendship.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1e/Cat_1.png"},{"name":"Dog","rarity":"uncommon","id":"dog","subtitle":"Animals","details":"Loyal farm pet adopted from Marnie, chasing butterflies between naps and bringing small gifts once friendship runs deep.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a4/Dog_1.png"},{"name":"Pet Turtle","rarity":"common","id":"pet-turtle","subtitle":"Animals","details":"Slow, shelled later pet for the farm, content at its bowl and occasionally leaving an unexpected gift for a patient friend.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e9/Turtle.png"},{"name":"Frog","rarity":"common","id":"frog","subtitle":"Animals","details":"Small green companion kept in a terrarium or met by island ponds, blinking at the world with total amphibian calm.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c3/Stone_Frog.png"},{"name":"Parrot","rarity":"common","id":"parrot","subtitle":"Animals","details":"Ginger Island bird that mimics, hints at hidden walnuts, and guards Leo's world of feathers, trees, and tropical rain.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a2/Stone_Parrot.png"},{"name":"Bear","rarity":"common","id":"bear","subtitle":"Animals","details":"Great forest visitor who asks after maple syrup and the tastes of the valley, rewarding curiosity with woodland wisdom.","image":"https://stardewvalleywiki.com/mediawiki/images/4/43/Bear_Statue.png"},{"name":"Raccoon","rarity":"common","id":"raccoon","subtitle":"Animals","details":"Stump-dwelling family in Cindersap Forest who trade crafted goods and seeds for the odd dishes they ask the farmer to find.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5e/Raccoon_Icon.png"},{"name":"Fruit Bat","rarity":"common","id":"fruit-bat","subtitle":"Animals","details":"Cave bat that leaves fruit on the farm cave floor overnight, a quiet alternative to mushrooms for patient gatherers.","image":"https://stardewvalleywiki.com/mediawiki/images/a/a2/CaveFruitBats.png"},{"name":"Stone Owl","rarity":"common","id":"stone-owl","subtitle":"Animals","details":"Mysterious stone statue that lands on the farm on a rare night, hooting in the records long after the event is over.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7c/Stone_Owl.png"},{"name":"Crow","rarity":"common","id":"crow","subtitle":"Animals","details":"Wild black bird that pecks at unguarded crops, kept honest by scarecrows and remembered in every farmer's first losses.","image":"https://stardewvalleywiki.com/mediawiki/images/f/fa/Crow.png"},{"name":"Squirrel","rarity":"common","id":"squirrel","subtitle":"Animals","details":"Quick woodland critter bounding through forest and town grass, never caught, never tamed, and always startled first.","image":"https://stardewvalleywiki.com/mediawiki/images/6/66/Squirrel_Figurine.png"},{"name":"Pepper Rex","rarity":"epic","id":"pepper-rex","subtitle":"Monsters","details":"Fire-breathing dinosaur of Skull Cavern's prehistoric floors, dropping dinosaur eggs and peppering delvers with flame.","image":"https://stardewvalleywiki.com/mediawiki/images/6/67/Pepper_Rex.png"},{"name":"Royal Serpent","rarity":"epic","id":"royal-serpent","subtitle":"Monsters","details":"Extra-long, swift serpent of the cavern's most dangerous depths, weaving between rocks and rewarding bold fighters.","image":"https://stardewvalleywiki.com/mediawiki/images/2/28/Royal_Serpent.png"},{"name":"Prismatic Slime","rarity":"rare","id":"prismatic-slime","subtitle":"Monsters","details":"Rainbow slime hunted for the Wizard's prismatic jelly, appearing rarely among ordinary slimes and shining as it hops.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c3/Prismatic_Slime.gif"},{"name":"Mummy","rarity":"rare","id":"mummy","subtitle":"Monsters","details":"Wrapped horror of Skull Cavern that rises again unless finished with a bomb, dropping cloth and solar essence alike.","image":"https://stardewvalleywiki.com/mediawiki/images/7/70/Mummy.png"},{"name":"Serpent","rarity":"rare","id":"serpent","subtitle":"Monsters","details":"Flying serpent of Skull Cavern, fast and furious over the rocks, dropping spicy eel for the delvers it fails to stop.","image":"https://stardewvalleywiki.com/mediawiki/images/8/89/Serpent.png"},{"name":"Haunted Skull","rarity":"rare","id":"haunted-skull","subtitle":"Monsters","details":"Floating skull of haunted and quarry depths, swift in packs and rumoured to drop rock candy on the luckiest kills.","image":"https://stardewvalleywiki.com/mediawiki/images/1/14/Haunted_Skull.png"},{"name":"Shadow Shaman","rarity":"rare","id":"shadow-shaman","subtitle":"Monsters","details":"Shadow caster of the Mines' deepest floors, healing its allies and dropping void essence for swords, rings, and totems.","image":"https://stardewvalleywiki.com/mediawiki/images/1/11/Shadow_Shaman.png"},{"name":"Skeleton Mage","rarity":"rare","id":"skeleton-mage","subtitle":"Monsters","details":"Bone caster of the dangerous Mines, flinging spells between its skeleton kin and guarding the deep with cold magic.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d3/Skeleton_Mage.png"},{"name":"Tiger Slime","rarity":"uncommon","id":"tiger-slime","subtitle":"Monsters","details":"Striped slime of the Volcano Dungeon, bouncing through lava country and occasionally leaving a tiger's slime egg behind.","image":"https://stardewvalleywiki.com/mediawiki/images/5/57/Tiger_Slime.png"},{"name":"Iridium Crab","rarity":"uncommon","id":"iridium-crab","subtitle":"Monsters","details":"Armoured crab disguised as an iridium node in Skull Cavern, snapping awake when struck and dropping ore and crab meat.","image":"https://stardewvalleywiki.com/mediawiki/images/e/ef/Iridium_Crab.png"},{"name":"Carbon Ghost","rarity":"uncommon","id":"carbon-ghost","subtitle":"Monsters","details":"Pale ghost of the dangerous depths, drifting through stone and dropping ectoplasm for the valley's strangest requests.","image":"https://stardewvalleywiki.com/mediawiki/images/5/5b/Carbon_Ghost.png"},{"name":"Magma Sprite","rarity":"uncommon","id":"magma-sprite","subtitle":"Monsters","details":"Fiery sprite of the Volcano Dungeon, darting over magma and dropping cinder shards and fiery forage on defeat.","image":"https://stardewvalleywiki.com/mediawiki/images/f/f2/Magma_Sprite.png"},{"name":"Dwarvish Sentry","rarity":"uncommon","id":"dwarvish-sentry","subtitle":"Monsters","details":"Mechanical guardian built by dwarves for the Volcano Dungeon, still standing watch and still carrying gadget parts.","image":"https://stardewvalleywiki.com/mediawiki/images/2/27/Dwarvish_Sentry.png"},{"name":"Green Slime","rarity":"common","id":"green-slime","subtitle":"Monsters","details":"First slime every farmer meets, hopping the Mines' top floors and the Secret Woods, dropping slime for a hundred crafts.","image":"https://stardewvalleywiki.com/mediawiki/images/7/7b/Green_Slime.png"},{"name":"Frost Jelly","rarity":"common","id":"frost-jelly","subtitle":"Monsters","details":"Icy slime of the Mines' frozen floors, jiggling with cold and occasionally dropping a frozen tear in its puddle.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9d/Frost_Jelly.png"},{"name":"Sludge","rarity":"common","id":"sludge","subtitle":"Monsters","details":"Dark wild slime of the deeper Mines and farm nights, tougher than its green cousins and rich in slime and surprises.","image":"https://stardewvalleywiki.com/mediawiki/images/4/47/SludgeMale.jpg"},{"name":"Dust Sprite","rarity":"common","id":"dust-sprite","subtitle":"Monsters","details":"Tiny coal sprite of the frozen floors, bouncing in packs, dropping coal by the handful, and beloved by delver and furnace.","image":"https://stardewvalleywiki.com/mediawiki/images/9/9a/Dust_Sprite.png"},{"name":"Rock Crab","rarity":"common","id":"rock-crab","subtitle":"Monsters","details":"Crab disguised as a loose rock on the Mines' upper floors, revealing claws when struck and dropping stone and crab.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d4/Rock_Crab.png"},{"name":"Lava Crab","rarity":"common","id":"lava-crab","subtitle":"Monsters","details":"Crab of the Mines' lava floors, camouflaged against hot rock and dropping bombs and crab from its scorched shell.","image":"https://stardewvalleywiki.com/mediawiki/images/1/1b/Lava_Crab.png"},{"name":"Bat","rarity":"common","id":"bat","subtitle":"Monsters","details":"Flapping pest of the Mines' upper floors, swooping at torchlight and dropping bat wings for lightning rods and potions.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ad/Bat.png"},{"name":"Frost Bat","rarity":"common","id":"frost-bat","subtitle":"Monsters","details":"Cold-weather bat of the frozen floors, swift in the dark and dropping bat wings and icy odds and ends alike.","image":"https://stardewvalleywiki.com/mediawiki/images/3/36/Frost_Bat.png"},{"name":"Lava Bat","rarity":"common","id":"lava-bat","subtitle":"Monsters","details":"Burning bat of the lava floors and volcano approaches, trailing sparks and dropping spicy, scorched monster loot.","image":"https://stardewvalleywiki.com/mediawiki/images/c/c5/Lava_Bat.png"},{"name":"Stone Golem","rarity":"common","id":"stone-golem","subtitle":"Monsters","details":"Living statue creeping the Mines' upper floors and wilderness farms at night, dropping stone from its crumbling fists.","image":"https://stardewvalleywiki.com/mediawiki/images/d/d4/Stone_Golem.png"},{"name":"Grub","rarity":"common","id":"grub","subtitle":"Monsters","details":"Soft larva of the Mines' earthy floors that pupates into a cave fly if left alone, dropping bug meat for bait.","image":"https://stardewvalleywiki.com/mediawiki/images/0/0c/Grub.png"},{"name":"Mutant Fly","rarity":"common","id":"mutant-fly","subtitle":"Monsters","details":"Buzzing mutant of the bug lair and dangerous depths, hatched from a grub gone wrong and dropping rich monster loot.","image":"https://stardewvalleywiki.com/mediawiki/images/6/69/Mutant_Fly.png"},{"name":"Skeleton","rarity":"common","id":"skeleton","subtitle":"Monsters","details":"Rattling skeleton of the Mines' middle floors, throwing its own bones and dropping fragments for mills and machines.","image":"https://stardewvalleywiki.com/mediawiki/images/2/23/Skeleton.png"},{"name":"Shadow Brute","rarity":"common","id":"shadow-brute","subtitle":"Monsters","details":"Muscular shadow of the deepest Mines, shrugging off knockback and dropping void essence from its dark, heavy frame.","image":"https://stardewvalleywiki.com/mediawiki/images/e/e0/Shadow_Brute.png"},{"name":"Ghost","rarity":"common","id":"ghost","subtitle":"Monsters","details":"Sheeted spirit of the Mines' middle floors, drifting through rock and dropping solar essence and geodes when banished.","image":"https://stardewvalleywiki.com/mediawiki/images/a/ab/Ghost.png"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
